static void prefix_scope(xui_document_snapshot snapshot, const char* source,
    const char* word, const struct prefix_fixture* fixture)
{
    const char* at = strstr(source, word); xui_doc_position_t position;
    xui_doc_node_info_t node = {0}; int quality; unsigned quotes = 0, notes = 0, paragraph = 0;
    TABLE_CHECK(at && xuiDocumentSourceToPosition(snapshot, (uint64_t)(at-source)+1,
        &position, &quality) == XUI_OK && quality == XUI_DOC_MAP_EXACT);
    node.iSize = sizeof(node);
    TABLE_CHECK(xuiDocumentSnapshotGetNode(snapshot, position.iNodeId, &node) == XUI_OK &&
        node.iKind == XUI_DOC_TEXT);
    for (uint64_t id = node.iParentId; id != XUI_DOCUMENT_ROOT;) {
        TABLE_CHECK(xuiDocumentSnapshotGetNode(snapshot, id, &node) == XUI_OK);
        paragraph += node.iKind == XUI_DOC_PARAGRAPH;
        quotes += node.iKind == XUI_DOC_QUOTE; notes += node.iKind == XUI_DOC_FOOTNOTE;
        TABLE_CHECK(node.iParentId != id); id = node.iParentId;
    }
    printf("SCOPE %s depth=%u word=%s paragraph=%u quotes=%u footnotes=%u\n",
        fixture->name, fixture->depth, word, paragraph, quotes, notes); fflush(stdout);
    TABLE_CHECK(paragraph == 1 && quotes == fixture->quotes && notes == fixture->notes);
}
